use kimo_core::{color::{interchange,scopes,managed},effects::Frame};
#[test]fn planar_float_preserves(){let f=Frame{w:2,h:1,d:vec![-0.25,2.,4.,0.5,0.18,1.25,-1.,1.]};assert_eq!(interchange::unpack(&interchange::pack(&f).unwrap(),2,1).unwrap(),f.d);assert!(interchange::unpack(&[0;3],2,1).is_err());assert!(interchange::unpack(&[],usize::MAX,2).is_err());}
#[test]fn float_fit_unbounded_alpha(){let f=Frame{w:2,h:1,d:vec![-0.25,-0.25,-0.25,1.,4.,4.,4.,1.]};let q=interchange::fit(&f,8,4,0.).unwrap();assert!(q.iter().any(|v|*v<0.));assert!(q.iter().any(|v|*v>3.99));assert!(interchange::fit(&f,0,4,0.).is_err());}
#[test]fn managed_scopes_gamut_nits(){let f=Frame{w:1,h:1,d:vec![1.,0.,0.,1.]};let w=managed::luma_weights(3);let v=scopes::data_domain(&f,256,-50.,500.,w,100.,false).unwrap();assert!((v["mean"][3].as_f64().unwrap()-w[0]*100.).abs()<1e-12);assert!(v["vectorscope_709"].is_null());}
#[test]fn tiff_float_fixture(){use tiff::encoder::{TiffEncoder,colortype::RGBA32Float};let path=std::env::temp_dir().join(format!("kimo-float-{}.tiff",std::process::id()));let f=std::fs::File::create(&path).unwrap();TiffEncoder::new(f).unwrap().write_image::<RGBA32Float>(2,1,&[-0.25,1.25,4.,1.,0.18,-0.1,2.,0.5]).unwrap();let q=interchange::tiff_frame(path.to_str().unwrap(),4096).unwrap();assert_eq!(q.d[0],-0.25);assert_eq!(q.d[2],4.);assert_eq!(q.d[7],0.5);assert!(interchange::tiff_frame(path.to_str().unwrap(),1).is_err());std::fs::remove_file(path).unwrap();}
#[test]fn malformed_float_shapes(){for n in [0,1,3,5,32]{let f=Frame{w:1,h:1,d:vec![0.;n]};assert!(interchange::pack(&f).is_err());assert!(interchange::fit(&f,16,16,0.).is_err());}let f=Frame{w:1,h:1,d:vec![f32::NAN,0.,0.,1.]};assert!(interchange::pack(&f).is_err());assert!(scopes::data_domain(&f,256,0.,1.,[f64::NAN,0.,0.],1.,false).is_err());}
#[test]fn alpha_correct_float_fit(){let f=Frame{w:2,h:1,d:vec![10.,0.,0.,0.,0.,2.,0.,1.]};let q=interchange::fit(&f,4,2,1.5).unwrap();for p in q.chunks_exact(4){if p[3]>0.{assert_eq!(p[0],0.);assert!((p[1]-2.).abs()<1e-6)}}}
#[test]fn exr_standard_metadata(){use exr::prelude::*;let path=std::env::temp_dir().join(format!("kimo-meta-{}.exr",std::process::id()));let f=Frame{w:2,h:1,d:vec![-0.25,1.25,4.,1.,0.18,0.1,2.,0.5]};interchange::write_exr(&f,path.to_str().unwrap(),3,100.).unwrap();let m=MetaData::read_from_file(&path,true).unwrap();let c=m.headers[0].shared_attributes.chromaticities.as_ref().unwrap();assert!((c.red.x()-0.713).abs()<1e-6);assert!((c.white.y()-0.33767).abs()<1e-6);assert_eq!(m.headers[0].own_attributes.white_luminance,Some(100.));std::fs::remove_file(path).unwrap();}
#[test]fn tiff_resize_in_working_linear(){use tiff::encoder::{TiffEncoder,colortype::RGB32Float};use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let path=std::env::temp_dir().join(format!("kimo-linear-fit-{}.tiff",std::process::id()));let file=std::fs::File::create(&path).unwrap();TiffEncoder::new(file).unwrap().write_image::<RGB32Float>(2,1,&[0.5,0.5,0.5,1.,1.,1.]).unwrap();let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16,"fps":25})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":1})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_property",&json!({"clip_id":c,"property":"fit","value":2})).unwrap();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"working_gamut":0,"input_gamut":0,"input_transfer":1}})).unwrap();render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();let f=render::render_frame(&s.project,0.,&s.cache).unwrap();assert!((f.d[(8*16+7)*4]-(managed::decode(1,0.5,100.)*0.5625+0.4375) as f32).abs()<1e-6);dispatch(&mut s,"set_property",&json!({"clip_id":c,"property":"input_transfer","value":2})).unwrap();render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();let f=render::render_frame(&s.project,0.,&s.cache).unwrap();assert!((f.d[(8*16+7)*4]-(managed::decode(2,0.5,100.)*0.5625+0.4375) as f32).abs()<1e-6);std::fs::remove_file(path).unwrap();}
#[test]fn exr_inspection_color_candidates(){let path=std::env::temp_dir().join(format!("kimo-inspect-{}.exr",std::process::id()));let f=Frame{w:2,h:1,d:vec![0.5;8]};for g in 0..8{interchange::write_exr(&f,path.to_str().unwrap(),g,100.).unwrap();let v=interchange::exr_info(path.to_str().unwrap()).unwrap();assert_eq!(v["layers"][0]["matching_gamut_ids"],serde_json::json!([g]));assert_eq!(v["layers"][0]["size"],serde_json::json!([2,1]));assert_eq!(v["layers"][0]["declared_white_luminance"],100.);interchange::validate_exr_source(path.to_str().unwrap()).unwrap();}std::fs::write(&path,b"malformed").unwrap();assert!(interchange::exr_info(path.to_str().unwrap()).is_err());std::fs::remove_file(path).unwrap();}
#[test]fn downsample_checker_preserves_energy(){let f=Frame{w:64,h:64,d:(0..4096).flat_map(|i|{let v=if ((i%64)+(i/64))%2==0{-0.25}else{4.};[v,v,v,1.]}).collect()};let q=interchange::fit(&f,7,5,2.).unwrap();for p in q.chunks_exact(4){assert!((p[0]-1.875).abs()<0.02);assert!((p[3]-1.).abs()<1e-6)}let q=interchange::fit(&f,1,1,2.).unwrap();assert!((q[0]-1.875).abs()<1e-6);}
#[test]fn downsample_transparent_color_no_fringe(){let f=Frame{w:2,h:1,d:vec![50.,0.,0.,0.,0.,4.,0.,1.]};let q=interchange::fit(&f,1,1,2.).unwrap();assert_eq!(q,vec![0.,4.,0.,0.5]);}
#[test]fn randomized_fit_energy_and_finite(){let mut seed=12345u32;for src in 1..18{for dst in 1..14{let mut data=Vec::new();for _ in 0..src*src{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);let v=(seed%10000) as f32/1000.-2.;data.extend([v,v,v,1.]);}let f=Frame{w:src,h:src,d:data};let q=interchange::fit(&f,dst,dst,2.).unwrap();assert!(q.iter().all(|v|v.is_finite()));if dst<src{let mean=f.d.chunks_exact(4).map(|p|p[0] as f64).sum::<f64>()/(src*src) as f64;let out=q.chunks_exact(4).map(|p|p[0] as f64).sum::<f64>()/(dst*dst) as f64;assert!((mean-out).abs()<1e-5);}}}}
#[test]fn float_tiff_export_roundtrip_tags(){let path=std::env::temp_dir().join(format!("kimo-tiff-write-{}.tif",std::process::id()));let f=Frame{w:2,h:1,d:vec![-0.25,4.,1.25,0.5,0.18,0.,2.,1.]};interchange::write_tiff(&f,path.to_str().unwrap(),3,100.).unwrap();let q=interchange::tiff_frame(path.to_str().unwrap(),4096).unwrap();assert_eq!(f.d,q.d);let v=interchange::tiff_info(path.to_str().unwrap()).unwrap();assert_eq!(v["sample_format"],serde_json::json!([3,3,3,3]));assert_eq!(v["extra_samples"],serde_json::json!([2]));let mut d=tiff::decoder::Decoder::new(std::fs::File::open(&path).unwrap()).unwrap();assert!(d.get_tag_ascii_string(tiff::tags::Tag::ImageDescription).unwrap().contains("gamut_id=3"));assert_eq!(v["white_point_xy"],serde_json::json!([0.32168,0.33767]));let mut bad=Frame{w:f.w,h:f.h,d:f.d.clone()};bad.d[3]=2.;assert!(interchange::write_tiff(&bad,path.to_str().unwrap(),3,100.).is_err());std::fs::remove_file(path).unwrap();}
#[test]fn fitted_cache_tracks_framing_and_source(){use tiff::encoder::{TiffEncoder,colortype::RGB32Float};use kimo_core::{commands::{Session,dispatch},render};use serde_json::json;let path=std::env::temp_dir().join(format!("kimo-cache-fit-{}.tif",std::process::id()));let write=|value:f32,width:u32|{let file=std::fs::File::create(&path).unwrap();TiffEncoder::new(file).unwrap().write_image::<RGB32Float>(width,1,&vec![value;width as usize*3]).unwrap();};write(0.5,2);let mut s=Session::new();dispatch(&mut s,"project_set",&json!({"width":16,"height":16})).unwrap();let a=dispatch(&mut s,"import_media",&json!({"path":path})).unwrap()["asset_id"].clone();let tr=dispatch(&mut s,"add_track",&json!({})).unwrap()["track_id"].clone();let c=dispatch(&mut s,"add_clip",&json!({"track_id":tr,"source_type":"media","asset_id":a,"start":0,"duration":1})).unwrap()["clip_id"].clone();dispatch(&mut s,"set_color_pipeline",&json!({"settings":{"enabled":true,"input_transfer":0,"working_gamut":0}})).unwrap();render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();assert_eq!(s.cache.frames_of(c.as_str().unwrap()).unwrap().get_float(0).unwrap()[3],0.);dispatch(&mut s,"set_property",&json!({"clip_id":c,"property":"fit","value":2})).unwrap();render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();assert_eq!(s.cache.frames_of(c.as_str().unwrap()).unwrap().get_float(0).unwrap()[3],1.);write(2.,3);render::prepare_at(&s.project,&mut s.cache,Some(0.)).unwrap();assert_eq!(s.cache.frames_of(c.as_str().unwrap()).unwrap().get_float(0).unwrap()[0],2.);std::fs::remove_file(path).unwrap();}
#[test]fn float_alpha_boundary_explicit(){for a in [-1.,1.001,f32::INFINITY,f32::NAN]{let f=Frame{w:1,h:1,d:vec![4.,-0.25,0.18,a]};assert!(interchange::fit(&f,16,16,0.).is_err());assert!(interchange::write_exr(&f,"/tmp/invalid-alpha.exr",3,100.).is_err());}let f=Frame{w:1,h:1,d:vec![f32::MAX,-f32::MAX,1.,0.5]};assert!(interchange::fit(&f,16,16,2.).unwrap().iter().all(|v|v.is_finite()));}
#[test]fn low_alpha_float_radiance_preserved(){for a in [1e-9f32,1e-20,1e-38]{let f=Frame{w:2,h:1,d:vec![4.,-0.25,0.18,a,4.,-0.25,0.18,a]};for (w,h) in [(1,1),(8,4)]{let q=interchange::fit(&f,w,h,2.).unwrap();for p in q.chunks_exact(4){assert_eq!(p[3],a);assert!((p[0]-4.).abs()<1e-6);assert!((p[1]+0.25).abs()<1e-6);assert!((p[2]-0.18).abs()<1e-6);}}}}

#[test]fn planar_alpha_contract(){for alpha in [-0.1,1.1,f32::NAN,f32::INFINITY]{let f=Frame{w:1,h:1,d:vec![-0.25,4.,0.18,alpha]};assert!(interchange::pack(&f).is_err());let mut bytes=Vec::new();for v in [4f32,0.18,-0.25,alpha]{bytes.extend(v.to_le_bytes())}assert!(interchange::unpack(&bytes,1,1).is_err());}let f=Frame{w:1,h:1,d:vec![-0.25,4.,0.18,1e-20]};assert_eq!(interchange::unpack(&interchange::pack(&f).unwrap(),1,1).unwrap(),f.d);}
